    --yy-desk: var(--yy-z10);
    --yy-input: var(--yy-z10);
    --yy-dim: var(--yy-z4);
    --yy-print: var(--yy-z10);
    --yy-print-edge: var(--yy-z7);
    --yy-floor: var(--yy-z8);
    --yy-fog: transparent;
    --yy-grain-img: none;
    --yy-glow: transparent;
    --yy-read-weight: var(--yy-day-read-weight);
    --yy-print-filter: var(--yy-day-print-filter);
    --yy-is-day: 1;

    
    --white20a: color-mix(in srgb, var(--SmartThemeBodyColor) 30%, transparent);
