:root:not(.dn-night) #left-nav-panel,
:root:not(.dn-night) #right-nav-panel {
    --yy-side-shade: color-mix(in srgb, var(--yy-z8) calc(var(--yy-light) * 100%), var(--yy-z9));
    background-color: var(--yy-z9);
    border-width: 0;
}

:root:not(.dn-night) #left-nav-panel {
    background-image: linear-gradient(90deg, var(--yy-side-shade), var(--yy-z9) 70%);
    box-shadow: inset -1px 0 0 var(--yy-z8), 0 16px 48px var(--SmartThemeShadowColor);
}

:root:not(.dn-night) #right-nav-panel {
    background-image: linear-gradient(270deg, var(--yy-side-shade), var(--yy-z9) 70%);
    box-shadow: inset 1px 0 0 var(--yy-z8), 0 16px 48px var(--SmartThemeShadowColor);
}

:root:not(.dn-night) #rm_print_characters_block {
    --yy-cs-hole: var(--yy-panel);
}

:root:not(.dn-night) #form_sheld {
    background-color: var(--yy-floor);
    background-image: var(--yy-wall-grain);
    border-top: 1px solid var(--yy-z7);
}

:root:not(.dn-night) #nonQRFormItems {
    background-color: var(--yy-z10);
    box-shadow: 0 6px 14px -8px color-mix(in srgb, var(--yy-z0) 35%, transparent);
}

:root:not(.dn-night) #nonQRFormItems::before {
    --c: var(--yy-z3);
}

:root:not(.dn-night) #chat .mes .ch_name .name_text::before {
    content: '\2014\2014\2002';
    letter-spacing: -0.05em;
    color: var(--yy-z3);
}

:root:not(.dn-night) .drawer-icon.closedIcon {
    color: var(--yy-z2);
}

:root:not(.dn-night) .drawer-icon.closedIcon:hover {
    color: var(--yy-mark);
}
/* ==== end themes/yinyan/day.css ==== */
}
